"use client";

import { useEffect, useState, useRef } from "react";
import { Box, Button, Typography, Paper, IconButton } from "@mui/material";
import { Close, NavigateNext, NavigateBefore } from "@mui/icons-material";

export type TourStep = {
  selector: string;
  title: string;
  description: string;
};

type TutorialTourProps = {
  steps: TourStep[];
  active: boolean;
  onClose: () => void;
};

export default function TutorialTour({ steps, active, onClose }: TutorialTourProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [rect, setRect] = useState<DOMRect | null>(null);
  const snapTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const step = steps[currentStep];

  useEffect(() => {
    if (!active) {
      setRect(null);
      setCurrentStep(0);
      return;
    }

    const updateRect = () => {
      if (!step) return;
      const element = document.querySelector(step.selector);
      if (element) {
        element.scrollIntoView({ block: "center", behavior: "smooth" });
        // Give a slight delay to allow smooth scroll to finish before capturing rect
        if (snapTimeoutRef.current) clearTimeout(snapTimeoutRef.current);
        snapTimeoutRef.current = setTimeout(() => {
          const r = element.getBoundingClientRect();
          setRect(r);
        }, 150);
      } else {
        setRect(null);
      }
    };

    updateRect();

    // Listen to resize and scroll
    window.addEventListener("resize", updateRect);
    window.addEventListener("scroll", updateRect, true);

    return () => {
      window.removeEventListener("resize", updateRect);
      window.removeEventListener("scroll", updateRect, true);
      if (snapTimeoutRef.current) clearTimeout(snapTimeoutRef.current);
    };
  }, [currentStep, active, step]);

  if (!active || !step) return null;

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep((c) => c + 1);
    } else {
      onClose();
      setCurrentStep(0);
    }
  };

  const handlePrev = () => {
    if (currentStep > 0) {
      setCurrentStep((c) => c - 1);
    }
  };

  // Determine tooltip positioning relative to the highlighted element
  let tooltipStyle: React.CSSProperties = {
    position: "fixed",
    zIndex: 100000,
    width: 320,
    transition: "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
  };

  if (rect) {
    const spaceBelow = window.innerHeight - rect.bottom;
    const spaceAbove = rect.top;
    
    // Position vertically
    if (spaceBelow > 220) {
      tooltipStyle.top = rect.bottom + 12;
    } else if (spaceAbove > 220) {
      tooltipStyle.bottom = (window.innerHeight - rect.top) + 12;
    } else {
      // Fallback to center screen if not enough space
      tooltipStyle.top = "50%";
      tooltipStyle.left = "50%";
      tooltipStyle.transform = "translate(-50%, -50%)";
    }

    // Position horizontally (align with highlight box left edge, clamping to screen edges)
    if (tooltipStyle.top !== "50%") {
      const leftPos = Math.max(16, Math.min(window.innerWidth - 336, rect.left));
      tooltipStyle.left = leftPos;
    }
  } else {
    // If no element found, center it in the viewport
    tooltipStyle.top = "50%";
    tooltipStyle.left = "50%";
    tooltipStyle.transform = "translate(-50%, -50%)";
  }

  return (
    <Box sx={{ position: "fixed", inset: 0, zIndex: 99999, pointerEvents: "none" }}>
      {/* Dark backdrop overlay masking outside elements */}
      <Box
        sx={{
          position: "fixed",
          inset: 0,
          backgroundColor: "rgba(11, 17, 32, 0.65)",
          pointerEvents: "auto",
          zIndex: -1,
        }}
        onClick={onClose}
      />

      {/* Highlight Box Frame */}
      {rect && (
        <Box
          sx={{
            position: "fixed",
            left: rect.left - 4,
            top: rect.top - 4,
            width: rect.width + 8,
            height: rect.height + 8,
            borderRadius: "12px",
            border: "2px dashed #6366f1",
            boxShadow: "0 0 0 9999px rgba(11, 17, 32, 0.75), 0 0 15px rgba(99, 102, 241, 0.4)",
            pointerEvents: "none",
            transition: "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
          }}
        />
      )}

      {/* Tooltip Card */}
      <Paper
        elevation={24}
        style={tooltipStyle}
        sx={{
          p: 2.5,
          borderRadius: "20px",
          backgroundColor: "#0f172a",
          border: "1px solid rgba(255, 255, 255, 0.08)",
          boxShadow: "0 20px 40px rgba(0, 0, 0, 0.5)",
          pointerEvents: "auto",
        }}
      >
        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", mb: 1.5 }}>
          <Typography sx={{ color: "#818cf8", fontSize: "0.75rem", fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.05em" }}>
            Langkah {currentStep + 1} dari {steps.length}
          </Typography>
          <IconButton onClick={onClose} size="small" sx={{ color: "#64748b", "&:hover": { color: "#f8fafc" }, mt: -0.5, mr: -0.5 }}>
            <Close sx={{ fontSize: 16 }} />
          </IconButton>
        </Box>

        <Typography sx={{ color: "#ffffff", fontSize: "0.9375rem", fontWeight: 700, mb: 1 }}>
          {step.title}
        </Typography>

        <Typography sx={{ color: "#cbd5e1", fontSize: "0.8125rem", lineHeight: 1.5, mb: 2.5 }}>
          {step.description}
        </Typography>

        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <Button
            size="small"
            onClick={onClose}
            sx={{ color: "#64748b", textTransform: "none", fontSize: "0.75rem", "&:hover": { color: "#94a3b8" } }}
          >
            Lewati
          </Button>

          <Box sx={{ display: "flex", gap: 1 }}>
            {currentStep > 0 && (
              <Button
                size="small"
                variant="outlined"
                onClick={handlePrev}
                startIcon={<NavigateBefore />}
                sx={{
                  color: "#cbd5e1",
                  borderColor: "rgba(255,255,255,0.15)",
                  textTransform: "none",
                  fontSize: "0.75rem",
                  borderRadius: "8px",
                  "&:hover": { borderColor: "rgba(255,255,255,0.3)", backgroundColor: "rgba(255,255,255,0.02)" }
                }}
              >
                Kembali
              </Button>
            )}

            <Button
              size="small"
              variant="contained"
              onClick={handleNext}
              endIcon={currentStep < steps.length - 1 ? <NavigateNext /> : undefined}
              sx={{
                backgroundColor: "#6366f1",
                color: "#ffffff",
                textTransform: "none",
                fontSize: "0.75rem",
                fontWeight: 600,
                borderRadius: "8px",
                "&:hover": { backgroundColor: "#4f46e5" }
              }}
            >
              {currentStep === steps.length - 1 ? "Selesai" : "Lanjut"}
            </Button>
          </Box>
        </Box>
      </Paper>
    </Box>
  );
}
