"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Box, Button, Typography, Paper } from "@mui/material";
import { HelpOutline, AutoAwesome, ShowChart, CreditCard, BarChart } from "@mui/icons-material";
import TutorialTour from "@/components/TutorialTour";
import { landingTourSteps } from "./tourSteps";

const getGreeting = () => {
  const hour = new Date().getHours();
  let greetings: string[] = [];

  if (hour >= 22 || hour < 4) {
    greetings = [
      "Halo, Night Owl!",
      "Belum tidur? Rehat dulu yuk",
      "Malam sunyi gini emang paling pas buat review keuangan",
      "Sambil santai malam, rapiin budget bentar yuk"
    ];
  } else if (hour >= 4 && hour < 11) {
    greetings = [
      "Selamat pagi! Siap produktif hari ini?",
      "Pagi! Udah ngopi belum hari ini?",
      "Awali pagi dengan cek kondisi keuanganmu",
      "Pagi! Yuk atur budget buat hari ini"
    ];
  } else if (hour >= 11 && hour < 15) {
    greetings = [
      "Siang! Jangan lupa catat pengeluaran makan siangmu ya",
      "Halo! Semoga aktivitas siangmu lancar jaya",
      "Siang! Coba cek cash flow sebentar yuk",
      "Siang! Tetap semangat jalanin hari"
    ];
  } else if (hour >= 15 && hour < 18) {
    greetings = [
      "Sore! Santai sejenak sambil cek portofolio yuk",
      "Sore yang adem, pas buat review transaksi hari ini",
      "Udah sore nih, beresin catatan keuangan dulu yuk",
      "Sore! Gimana harimu sejauh ini?"
    ];
  } else {
    greetings = [
      "Malam! Gimana, aman gak dompet hari ini?",
      "Malam! Waktunya santai sambil rekap pengeluaran",
      "Yuk cek kesehatan finansialmu malam ini",
      "Malam! Jangan lupa catat transaksi hari ini ya"
    ];
  }

  const randomIndex = Math.floor(Math.random() * greetings.length);
  return greetings[randomIndex];
};

export default function LandingPage() {
  const [tourActive, setTourActive] = useState(false);
  const [hoveredCardId, setHoveredCardId] = useState<string | null>(null);
  const [clickedCardId, setClickedCardId] = useState<string | null>(null);
  const [greeting, setGreeting] = useState("Selamat Datang");

  useEffect(() => {
    setGreeting(getGreeting());
    const handleClickOutside = () => {
      setClickedCardId(null);
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  const startTour = () => {
    if (typeof window !== "undefined") {
      window.dispatchEvent(new Event("finter-tour-start"));
    }
    setTimeout(() => {
      setTourActive(true);
    }, 150);
  };

  return (
    <Box
      sx={{
        minHeight: "100%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        px: 4,
        py: 8,
        background: "radial-gradient(circle at 50% 30%, rgba(99, 102, 241, 0.15), transparent 60%)",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Top Right "Lihat Tutorial" Button */}
      <Button
        variant="outlined"
        onClick={startTour}
        startIcon={<HelpOutline sx={{ fontSize: 16 }} />}
        sx={{
          position: "absolute",
          top: { xs: 16, sm: 24 },
          right: { xs: 16, sm: 24 },
          color: "#818cf8",
          borderColor: "rgba(129, 140, 248, 0.3)",
          fontWeight: 600,
          fontSize: "0.75rem",
          px: 2,
          py: 0.75,
          borderRadius: "10px",
          textTransform: "none",
          backgroundColor: "rgba(129, 140, 248, 0.03)",
          transition: "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
          zIndex: 10,
          "&:hover": {
            borderColor: "#818cf8",
            backgroundColor: "rgba(129, 140, 248, 0.08)",
          },
        }}
      >
        Lihat Tutorial
      </Button>

      {/* Hero Header */}
      <Box sx={{ textAlign: "center", maxWidth: 900, mb: 6, zIndex: 2 }}>
        <Typography
          variant="h2"
          sx={{
            fontWeight: 800,
            fontSize: { xs: "1.5rem", md: "2.125rem" },
            lineHeight: 1.2,
            color: "#ffffff",
          }}
        >
          {greeting}
        </Typography>
      </Box>

      {/* Feature cards Row */}
      <Box
        sx={{
          display: "flex",
          flexDirection: { xs: "column", sm: "row" },
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
          gap: 2,
          width: "100%",
          maxWidth: 1000,
          zIndex: 2,
        }}
      >
        {[
          {
            title: "Asisten Finter AI",
            desc: "Pencatatan transaksi instan lewat chat, konsultasi anggaran, serta analisis portofolio otomatis dipandu asisten virtual cerdas.",
            icon: <AutoAwesome sx={{ fontSize: 20, color: "#818cf8" }} />,
          },
          {
            title: "Investasi",
            desc: "Pantau kepemilikan dan performa portofolio Saham, ETF, Crypto, Obligasi, Properti, hingga Deposito secara terpadu.",
            icon: <ShowChart sx={{ fontSize: 20, color: "#34d399" }} />,
          },
          {
            title: "Liabilitas",
            desc: "Kelola outstanding pinjaman bank, limit kartu kredit, paylater, cicilan, dan pengingat jatuh tempo secara cerdas.",
            icon: <CreditCard sx={{ fontSize: 20, color: "#f43f5e" }} />,
          },
          {
            title: "Visualisasi Laporan",
            desc: "Analisis tren arus kas, persentase alokasi pengeluaran, saving rate, dan indikator kesehatan finansial secara real-time.",
            icon: <BarChart sx={{ fontSize: 20, color: "#06b6d4" }} />,
          },
        ].map((feat, index) => {
          const isOpen = clickedCardId === feat.title || hoveredCardId === feat.title;
          return (
            <Paper
              key={feat.title}
              elevation={0}
              onMouseEnter={() => setHoveredCardId(feat.title)}
              onMouseLeave={() => setHoveredCardId(null)}
              onClick={(e) => {
                e.stopPropagation();
                setClickedCardId(clickedCardId === feat.title ? null : feat.title);
              }}
              sx={{
                position: "relative",
                backgroundColor: "rgba(15, 23, 42, 0.6)",
                border: "1px solid rgba(255, 255, 255, 0.05)",
                borderRadius: "12px",
                p: 1.75,
                backdropFilter: "blur(8px)",
                transition: "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
                cursor: "pointer",
                zIndex: isOpen ? 20 : 1,
                width: { xs: "100%", sm: "auto" },
                minWidth: { xs: "100%", sm: "max-content" },
                flexShrink: 0,
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                "&:hover": {
                  borderColor: "rgba(99, 102, 241, 0.3)",
                  backgroundColor: "rgba(15, 23, 42, 0.8)",
                },
              }}
            >
              <Box sx={{ display: "flex", alignItems: "center", gap: 1.25 }}>
                {feat.icon}
                <Typography sx={{ color: "#f8fafc", fontWeight: 600, fontSize: "0.875rem" }}>
                  {feat.title}
                </Typography>
              </Box>

              {/* Absolutely positioned description popover overlay */}
              {isOpen && (
                <Box
                  sx={{
                    position: "absolute",
                    top: "calc(100% + 8px)",
                    left: index < 2 ? 0 : "auto",
                    right: index >= 2 ? 0 : "auto",
                    backgroundColor: "#0d1527",
                    border: "1px solid rgba(99, 102, 241, 0.25)",
                    borderRadius: "12px",
                    p: 1.75,
                    width: { xs: "280px", sm: "max-content" },
                    maxWidth: { xs: "280px", sm: "360px" },
                    zIndex: 20,
                    backdropFilter: "blur(8px)",
                    boxShadow: "0 15px 35px rgba(0, 0, 0, 0.6)",
                    animation: "fadeInDown 0.15s ease-out forwards",
                    "@keyframes fadeInDown": {
                      from: { opacity: 0, transform: "translateY(-4px)" },
                      to: { opacity: 1, transform: "translateY(0)" }
                    }
                  }}
                >
                  <Typography sx={{ color: "#94a3b8", fontSize: "0.8125rem", lineHeight: 1.5 }}>
                    {feat.desc}
                  </Typography>
                </Box>
              )}
            </Paper>
          );
        })}
      </Box>

      {/* Tutorial Tour Overlay Component */}
      <TutorialTour
        steps={landingTourSteps}
        active={tourActive}
        onClose={() => setTourActive(false)}
      />
    </Box>
  );
}
